class Solution:
    def thirdMax(self, nums: list[int]) -> int:
        top=[]
        for x in nums:
            if x in top:continue
            top.append(x);top.sort(reverse=True);top=top[:3]
        return top[2] if len(top)==3 else top[0]

class Solution {
    public int thirdMax(int[] nums) {
        long a=Long.MIN_VALUE,b=Long.MIN_VALUE,c=Long.MIN_VALUE;
        for(int x:nums){if(x==a||x==b||x==c)continue;if(x>a){c=b;b=a;a=x;}else if(x>b){c=b;b=x;}else if(x>c)c=x;}
        return (int)(c==Long.MIN_VALUE?a:c);
    }
}

class Solution:
    def addStrings(self, num1: str, num2: str) -> str:
        i=len(num1)-1;j=len(num2)-1;carry=0;out=[]
        while i>=0 or j>=0 or carry:
            a=ord(num1[i])-48 if i>=0 else 0
            b=ord(num2[j])-48 if j>=0 else 0
            total=a+b+carry;out.append(str(total%10));carry=total//10;i-=1;j-=1
        return ''.join(reversed(out))

class Solution {
    public String addStrings(String num1,String num2) {
        int i=num1.length()-1,j=num2.length()-1,carry=0;StringBuilder out=new StringBuilder();
        while(i>=0||j>=0||carry>0){int a=i>=0?num1.charAt(i--)-'0':0,b=j>=0?num2.charAt(j--)-'0':0;int sum=a+b+carry;out.append(sum%10);carry=sum/10;}
        return out.reverse().toString();
    }
}

class Solution:
    def canPartition(self, nums: list[int]) -> bool:
        total=sum(nums)
        if total%2:return False
        target=total//2;dp=[False]*(target+1);dp[0]=True
        for x in nums:
            for s in range(target,x-1,-1):dp[s]=dp[s] or dp[s-x]
        return dp[target]

class Solution {
    public boolean canPartition(int[] nums) {
        int total=0;for(int x:nums)total+=x;if((total&1)==1)return false;int target=total/2;boolean[]dp=new boolean[target+1];dp[0]=true;
        for(int x:nums)for(int s=target;s>=x;s--)dp[s]=dp[s]||dp[s-x];return dp[target];
    }
}

class Solution:
    def pacificAtlantic(self, heights: list[list[int]]) -> list[list[int]]:
        if not heights or not heights[0]:return []
        m,n=len(heights),len(heights[0]);pac=set();atl=set()
        def dfs(r,c,seen):
            if (r,c) in seen:return
            seen.add((r,c))
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                x,y=r+dr,c+dc
                if 0<=x<m and 0<=y<n and heights[x][y]>=heights[r][c]:dfs(x,y,seen)
        for r in range(m):
            dfs(r,0,pac);dfs(r,n-1,atl)
        for c in range(n):
            dfs(0,c,pac);dfs(m-1,c,atl)
        return [[r,c] for r in range(m) for c in range(n) if (r,c) in pac and (r,c) in atl]

import java.util.*;
class Solution {
    private int[][]h;private int m,n;private boolean[][]p,a;private final int[][]d={{1,0},{-1,0},{0,1},{0,-1}};
    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        List<List<Integer>>out=new ArrayList<>();if(heights.length==0||heights[0].length==0)return out;h=heights;m=h.length;n=h[0].length;p=new boolean[m][n];a=new boolean[m][n];
        for(int r=0;r<m;r++){dfs(r,0,p);dfs(r,n-1,a);}for(int c=0;c<n;c++){dfs(0,c,p);dfs(m-1,c,a);}
        for(int r=0;r<m;r++)for(int c=0;c<n;c++)if(p[r][c]&&a[r][c])out.add(Arrays.asList(r,c));return out;
    }
    private void dfs(int r,int c,boolean[][]seen){if(seen[r][c])return;seen[r][c]=true;for(int[]v:d){int x=r+v[0],y=c+v[1];if(x>=0&&x<m&&y>=0&&y<n&&h[x][y]>=h[r][c])dfs(x,y,seen);}}
}

class Solution:
    def countBattleships(self, board: list[list[str]]) -> int:
        if not board:return 0
        m,n=len(board),len(board[0]);count=0
        for r in range(m):
            for c in range(n):
                if board[r][c]!='X':continue
                if r>0 and board[r-1][c]=='X':continue
                if c>0 and board[r][c-1]=='X':continue
                count+=1
        return count

class Solution {
    public int countBattleships(char[][] board) {
        int m=board.length;if(m==0)return 0;int n=board[0].length,count=0;
        for(int r=0;r<m;r++)for(int c=0;c<n;c++)if(board[r][c]=='X'&&(r==0||board[r-1][c]!='X')&&(c==0||board[r][c-1]!='X'))count++;
        return count;
    }
}

class Solution:
    def findMaximumXOR(self, nums: list[int]) -> int:
        ans=mask=0
        for bit in range(31,-1,-1):
            mask|=1<<bit;candidate=ans|(1<<bit)
            prefixes={x&mask for x in nums}
            if any((candidate^p) in prefixes for p in prefixes):ans=candidate
        return ans

import java.util.*;
class Solution {
    public int findMaximumXOR(int[] nums) {
        int ans=0,mask=0;
        for(int bit=31;bit>=0;bit--){mask|=1<<bit;int candidate=ans|(1<<bit);Set<Integer>p=new HashSet<>();for(int x:nums)p.add(x&mask);boolean ok=false;for(int x:p)if(p.contains(candidate^x)){ok=true;break;}if(ok)ans=candidate;}
        return ans;
    }
}

